	set cmps = ""
	Set tProductionName = ##class(Ens.Director).GetActiveProductionName()

   		// $$$LOGINFO( "GetComponents " _ $NAMESPACE _ ", getProductionItems: " _ tProductionName)

   		Set tProduction = ##class(Ens.Config.Production).%OpenId(tProductionName,,.tStatus)


   		Set tStatus = ##class(Ens.Director).getProductionItems(tProduction,.tProductionDefinition)

   		If ($DATA(tProductionDefinition) = 10) {
	   		Set tConfigName = ""
			For { 
				Set tConfigName = $ORDER(tProductionDefinition(tConfigName))
				Quit:(tConfigName = "")
				Set tConfigBusinessType = tProductionDefinition(tConfigName,"BusinessType")
				Set tConfigBusinessType = $CASE(tConfigBusinessType,
              							1:"Service",
              							2:"Process",
              							3:"Operation",
              							:"Unknown")
				if ( (compType = "All") || (tConfigBusinessType = compType))
				{				
					set cmps = cmps _ "," _ tConfigName
				}

			}
   		}
   		return cmps

grp = zenPage.getComponentById('redeployGrp');
newComp = zenPage.getComponentById('newComp');
var nm = zenPage.getComponentById('components').getValue()
if(nm == '')
{
	grp.setProperty('hidden', true);
	newComp.setProperty('hidden', false);
	zenPage.getComponentById('comboboxdeployType').setProperty('selectedIndex', 1);
	zenPage.getComponentById('comboboxdeployType').setValue("new")

}
else
{
	grp.setProperty('hidden', false);
	newComp.setProperty('hidden', true);
	zenPage.getComponentById('comboboxdeployType').setProperty('selectedIndex', 2);
	zenPage.getComponentById('comboboxdeployType').setValue("update")
}
